@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1317  cases=42
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-149
  @fn seedItems(h, takes, srcLen)  @ 165-170
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 172-181
  @fn trackList(trackCount)  @ 183-189
  @fn mapTracker(harness, inst, trackCount)  @ 193-207
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 211-219
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 222-231
  @case 'focusState before any render returns both bits false'  [harness]  @ 234-241
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 247-260
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 264-281
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 287-308
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 314-332
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 339-357
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 363-396
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 400-424
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 430-460
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 464-485
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 489-502
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 508-542
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 546-560
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 564-587
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 594-611
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 615-638
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 642-665
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 669-704
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 708-724
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 733-751
  @case 'the map window centres time on the current instance, holding its top on screen'  [harness]  @ 755-767
  @case 'with the tracker in no instance the map window centres on the edit cursor'  [harness]  @ 771-778
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 782-793
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 797-824
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 828-852
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 859-880
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 886-910
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 917-936
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 940-959
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 963-985
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 991-1009
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1013-1031
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1035-1057
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1061-1085
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1091-1146
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1154-1183
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1189-1232
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1238-1252
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1259-1291
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1295-1315

